//! Additive public elementary-path controls for FR-GILT-07/08/12/13/20/22.
//!
//! Threshold yields are independently target-selected from the frozen source
//! model at Decimal160/240 before executing these tests. They are not prices
//! generated by the Rust implementation. Native elementary comparisons remain
//! conditional on TOL-GILT-ELEMENTARY, not a portable libm precision theorem.

#![expect(clippy::expect_used, reason = "explicit valid boundary-test inputs")]
#![expect(clippy::panic, reason = "unexpected typed outcomes fail these tests")]

use sabiquant::amounts::DecimalAmount;
use sabiquant::bonds::{ConventionalGilt, GiltError, GiltPricingPlan};
use sabiquant::calendar::EndOfMonth;
use sabiquant::error::{NonFinite, ValueError};
use sabiquant::rates::RateError;
use sabiquant::time::Date;
use std::ops::Bound;

const PERIODS: u32 = 2_000;
const H_YIELD_BITS: u64 = 0xbfe3_1eb9_e43a_71b5;
const Z_YIELD_BITS: u64 = 0x3fec_e4a4_2b68_a4cb;

fn gilt() -> ConventionalGilt {
    let issue = Date::from_ymd(2000, 1, 1).expect("valid issue");
    let dates: Vec<_> = (0..=PERIODS)
        .map(|step| {
            issue
                .checked_add_months(6 * i64::from(step))
                .expect("cycle ends in year 3000")
        })
        .collect();
    ConventionalGilt::new(
        issue,
        dates[dates.len() - 1],
        DecimalAmount::new(0, 0).expect("zero coupon"),
        dates[1],
        dates.clone(),
        dates[1..].to_vec(),
        EndOfMonth::Ignore,
        2_001,
    )
    .expect("complete regular cycle and explicit compatible cutoffs")
}

fn boundary(error: GiltError, threshold: f64) {
    match error {
        GiltError::Rate {
            index: Some(2_000),
            phase: "discount factor",
            cause:
                RateError::NumericalBoundary {
                    quantity: "discount factor",
                    logarithm,
                    ..
                },
            ..
        } => {
            // Yield-coordinate rounding plus the conditional 4u log and one
            // exponent RN budgets are < 6 ULP here, independently of the
            // implementation's outward-guard arithmetic.
            let lower = (0..6).fold(threshold, |x, _| x.next_down());
            let upper = (0..6).fold(threshold, |x, _| x.next_up());
            assert!(lower <= logarithm && logarithm <= upper);
        }
        other => panic!("expected final-factor NumericalBoundary: {other:?}"),
    }
}

/// FR-GILT-07/08/20: source-zero coupons still observe every factor. At issue,
/// lambda_final=2000. Select y=RN(2*(exp(-B/2000)-1)), with B the exact
/// overflow or half-MIN_SUB exponent boundary. Both Decimal160 and240 give
/// the constants above; neither yield was selected from a production result.
#[test]
fn both_exponential_midpoints_have_final_indexed_boundary_errors() {
    let instrument = gilt();
    let plan = GiltPricingPlan::new(&instrument, instrument.issue_date(), 2_000)
        .expect("all 2000 actual zero coupons remain buyer bundles");
    assert_eq!(plan.bundle_count(), 2_000);
    for (yield_bits, threshold_bits) in [
        (H_YIELD_BITS, 0x4086_2e42_fefa_39ef),
        (Z_YIELD_BITS, 0xc087_4910_d52d_3052),
    ] {
        let y = f64::from_bits(yield_bits);
        boundary(
            plan.evaluate(y).expect_err("uncertain final factor"),
            f64::from_bits(threshold_bits),
        );
        boundary(
            plan.risk(y).expect_err("same per-bundle factor policy"),
            f64::from_bits(threshold_bits),
        );
    }
}

/// FR-GILT-07/08/20: moving128 yield ULPs changes the final exponent by more
/// than 1e-11, outside the guard (<8e-13). No prior factor is close: its
/// exponent is at least0.35 from the relevant threshold. The finite H side
/// reaches the distinct one-round source-PV overflow; the other three sides
/// retain their ordinary factor/source outcomes.
#[test]
fn both_sides_outside_each_guard_keep_distinct_runtime_classification() {
    let instrument = gilt();
    let plan = GiltPricingPlan::new(&instrument, instrument.issue_date(), 2_000)
        .expect("valid retained zero-coupon plan");
    match plan.evaluate(f64::from_bits(H_YIELD_BITS + 128)) {
        Err(GiltError::Rate {
            index: Some(2_000),
            phase: "discount factor",
            cause:
                RateError::Value(ValueError::ResultNotFinite {
                    quantity: "discount factor",
                    value: NonFinite::PositiveInfinity,
                    ..
                }),
            ..
        }) => {}
        other => panic!("H overflow side: {other:?}"),
    }
    match plan.evaluate(f64::from_bits(H_YIELD_BITS - 128)) {
        Err(GiltError::Value {
            index: Some(2_000),
            phase: "source present value",
            cause:
                ValueError::ResultNotFinite {
                    quantity: "gilt present value",
                    value: NonFinite::PositiveInfinity,
                    ..
                },
            ..
        }) => {}
        other => panic!("finite H factor then PV overflow: {other:?}"),
    }
    match plan.evaluate(f64::from_bits(Z_YIELD_BITS + 128)) {
        Err(GiltError::Rate {
            index: Some(2_000),
            phase: "discount factor",
            cause:
                RateError::Value(ValueError::ResultOutOfDomain {
                    quantity: "discount factor",
                    value,
                    domain,
                    ..
                }),
            ..
        }) => {
            assert_eq!(value.to_bits(), 0);
            assert_eq!(domain.lower(), Bound::Excluded(0.0));
            assert_eq!(domain.upper(), Bound::Unbounded);
        }
        other => panic!("Z zero side: {other:?}"),
    }
    let finite = plan
        .evaluate(f64::from_bits(Z_YIELD_BITS - 128))
        .expect("finite positive subnormal factor outside Z guard");
    // The final source amount is exactly100 and the observed factor is
    // MIN_SUB; their single IEEE product is exactly100 MIN_SUB.
    assert_eq!(finite.dirty_per_100().to_bits(), 100);
}

/// FR-GILT-07/12/13/22: the two neighbors of each signed2^-52 branch boundary
/// and equality are compared to independently outward-rounded ideal prices.
/// With lambda=2000 and |y|<=next_up(2^-52), |z|<2^-42. The log/tiny-remainder
/// contribution to price is <2^-82; the conditional exp allowance is <2^-44,
/// and source-PV RN adds <=2^-47. Their sum is <2^-43. The enclosing bit cells
/// below are rounded outward from ideal_price +/-2^-43 at both160/240 digits.
#[test]
fn both_signed_tiny_branch_boundaries_respect_conditional_ideal_bounds() {
    let instrument = gilt();
    let plan = GiltPricingPlan::new(&instrument, instrument.issue_date(), 2_000)
        .expect("valid source plan");
    for (yield_bits, lower_bits, upper_bits) in [
        (
            0x3caf_ffff_ffff_ffff,
            0x4058_ffff_ffff_f9dd,
            0x4058_ffff_ffff_f9ee,
        ),
        (
            0x3cb0_0000_0000_0000,
            0x4058_ffff_ffff_f9dd,
            0x4058_ffff_ffff_f9ee,
        ),
        (
            0x3cb0_0000_0000_0001,
            0x4058_ffff_ffff_f9dd,
            0x4058_ffff_ffff_f9ee,
        ),
        (
            0xbcaf_ffff_ffff_ffff,
            0x4059_0000_0000_0612,
            0x4059_0000_0000_0623,
        ),
        (
            0xbcb0_0000_0000_0000,
            0x4059_0000_0000_0612,
            0x4059_0000_0000_0623,
        ),
        (
            0xbcb0_0000_0000_0001,
            0x4059_0000_0000_0612,
            0x4059_0000_0000_0623,
        ),
    ] {
        let y = f64::from_bits(yield_bits);
        let lower = f64::from_bits(lower_bits);
        let upper = f64::from_bits(upper_bits);
        let valuation = plan.evaluate(y).expect("finite tiny-branch price");
        let risk = plan.risk(y).expect("finite extended-risk construction");
        for observed in [valuation.dirty_per_100(), risk.dirty_per_100()] {
            assert!(lower <= observed && observed <= upper, "y={y:?}");
        }
    }
}
